///     const B: bool;
///
///     type SomeType;
///
///     fn a();
///     fn c();
///     fn b();
/// }
/// ```
///
/// Use instead:
/// ```no_run
/// trait TraitOrdered {
///     const A: bool;
///     const B: bool;
///     const C: bool;
///
///     type SomeType;
///
///     fn a();
///     fn b();
///     fn c();
/// }
/// ```
///
